const UA='Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/140.0.0.0 Safari/537.36';
const names=['core/get-site-info','core/get-user-info','core/get-post','core/list-posts','core/create-post','core/update-post','core/upload-media','core/install-plugin','core/activate-plugin','elementor/get-site-info','elementor/create-page'];
for(const name of names) for(const method of ['GET','POST']){try{let opts={method,redirect:'manual',headers:{'user-agent':UA,'accept':'application/json','content-type':'application/json'}};if(method==='POST')opts.body=JSON.stringify({input:{}});const path='/wp-json/wp-abilities/v1/abilities/'+name+'/run';const r=await fetch('https://www.riseup.co.il'+path,opts);const b=await r.text();console.log('ABILITY',JSON.stringify({method,name,status:r.status,len:b.length,body:b.slice(0,1000)}));}catch(e){console.log('ERR',method,name,String(e))}}
